import Foundation

// Public eID PKI chain (Go reference pades/internal/eidcrypto/chain = ca-eidmongolia-mn pki/chain, 2026-09-28 04/05).
// Trust anchor = 01 only; 02–05 build chains. Generated from the PEM files — do not edit by hand.
enum EidChain {
    static let root01 = ""
    static let ca02 = ""
    static let ca03 = ""
    static let ca04 = ""
    static let ca05 = ""

    private static func cert(_ b64: String) -> X509Cert {
        // Fixed public certificates: a parse failure is a build defect.
        try! X509Cert(der: [UInt8](Data(base64Encoded: b64)!))
    }

    /// Mongolian National Root CA (01).
    static var nationalRoot: X509Cert { cert(root01) }
    /// 02, 03, 04, 05.
    static var intermediates: [X509Cert] { [ca02, ca03, ca04, ca05].map(cert) }
    /// eID citizen/organisation issuing CAs (04, 05).
    static var issuers: [X509Cert] { [ca04, ca05].map(cert) }
}
